import React from 'react';
import Review from '../components/Review';
import { reviews, colors, sliderSettings } from '../reviews/reviewsData';
import 'tailwindcss/tailwind.css';
import './Home.css'; 

import Slider from 'react-slick';
import "slick-carousel/slick/slick.css"; 
import "slick-carousel/slick/slick-theme.css";

const adjustedSliderSettings = {
    ...sliderSettings,
    dots: false,
};

const ReviewPage: React.FC = () => {
    const offsetIndexes = [0, 2, 4, 6, 8]; // Review offsets for each row

    return (
      <div style={{ minHeight: '100vh' }} className="border-b-4 border-black">
        <section className="mt-0 space-y-8">
          <div className="flex flex-col items-center bg-white p-6">
            <h1 className="text-6xl font-bold pb-2">178 Reviews</h1>
            <div className="flex">
              {[...Array(5)].map((_, i) => (
                <span key={i} className="text-yellow-500 text-4xl">★</span>
              ))}
            </div>
          </div>
        </section>
        <div className="bg-white">
          {offsetIndexes.map((offset, rowIndex) => (
            <section key={rowIndex} className="space-y-4 bg-white rounded-lg min-h-[400px]">
              <Slider {...adjustedSliderSettings}>
                {[...Array(offset)].map((_, idx) => (
                  <div key={`placeholder-${idx}`} className="p-2 opacity-0"> {/* Empty placeholder for offset */}
                    <Review 
                      reviewer=""
                      lessons={0}
                      quote=""
                      backgroundColor="transparent"
                    />
                  </div>
                ))}
                {reviews.map((review, idx) => (
                  <div key={idx} className="p-2">
                    <Review 
                      reviewer={review.reviewer}
                      lessons={review.lessons}
                      quote={review.quote}
                      backgroundColor={colors[idx % colors.length]}
                    />
                  </div>
                ))}
              </Slider>
            </section>
          ))}
        </div>
      </div>
    );
  };

  export default ReviewPage;
